#[derive(Copy, Clone, PartialEq, Eq)]
pub struct Money<C: Currency> { amount: Decimal, _c: PhantomData<C> }

impl<C: Currency> Money<C> {
    pub fn add(self, other: Self) -> Self {
        Self { amount: (self.amount + other.amount).round_dp(C::SCALE), _c: PhantomData }
    }
}

