#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Money<C: Currency>(i64, PhantomData<C>);

impl<C: Currency> Add for Money<C> {
    fn add(self, rhs: Self) -> Self {
        Self(self.0.checked_add(rhs.0).expect("amount overflow"), PhantomData)
    }
}
